 ## 1.4.2 - 2026-09-30

diff --git a/src/items.js b/src/items.js
index b1cae5b..69c9617 100644
--- a/src/items.js
+++ b/src/items.js
@@ -1,15 +1,46 @@
 import { fetchItems, saveItem } from "./store.js";

+// Highest id handed out so far, so ids stay unique even after removals.
+let lastId = 0;
+
 /** Items that carry `tag`. */
 export async function findByTag(tag) {
   const items = await fetchItems();
   return items.filter((item) => item.tags.includes(tag));
 }

-/** Adds an item with the next free id. */
+// Checks an item against docs/DATA.md and returns it in stored form; throws if invalid.
+function normalize(item) {
+  if (!item || typeof item !== "object") throw new Error("Item must be an object.");
+  const { name, qty, unit = "", tags = [], expires } = item;
+  if (typeof name !== "string" || !name.trim()) throw new Error("Item needs a name.");
+  if (!Number.isInteger(qty) || qty < 0)
+    throw new Error("Item qty must be a whole number, 0 or more.");
+  if (typeof unit !== "string" || !/^[A-Za-z]*$/.test(unit))
+    throw new Error("Item unit must be a word or empty.");
+  if (!Array.isArray(tags) || tags.some((t) => typeof t !== "string" || !t.trim()))
+    throw new Error("Item tags must be non-empty strings.");
+  const out = {
+    ...item,
+    name: name.trim().toLowerCase(),
+    qty,
+    unit,
+    tags: [...new Set(tags.map((t) => t.trim().toLowerCase()))].sort(),
+  };
+  if (expires !== undefined) {
+    const m = typeof expires === "string" && /^(\d{4})-(\d{2})-(\d{2})$/.exec(expires);
+    const d = m && new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
+    if (!d || d.toISOString().slice(0, 10) !== expires)
+      throw new Error("Item expires must be a date written YYYY-MM-DD.");
+  }
+  return out;
+}
+
+/** Validates an item, then adds it with the next free id; throws an Error if invalid. */
 export async function addItem(item) {
-  if (!item.name) throw new Error("Item needs a name.");
+  const valid = normalize(item);
   const items = await fetchItems();
-  const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  const id = Math.max(lastId, ...items.map((i) => i.id)) + 1;
+  lastId = id;
+  return saveItem({ ...valid, id });
 }
